[CmdletBinding()]
param([string]$Destination = (Join-Path $env:LOCALAPPDATA 'Programs\ICE'), [string]$BaseUrl = $env:ICE_RELEASE_BASE_URL)
$ErrorActionPreference='Stop'; if (-not $BaseUrl) { $BaseUrl='https://github.com/OWNER/ice-binaries/releases/latest/download' }
$root=[IO.Path]::GetFullPath($Destination).TrimEnd('\'); $tmp=Join-Path ([IO.Path]::GetTempPath()) ('ice-' + [guid]::NewGuid()); New-Item -ItemType Directory -Path $tmp | Out-Null
try { $asset=Join-Path $tmp 'ice.exe'; $sums=Join-Path $tmp 'SHA256SUMS.txt'; Invoke-WebRequest "$BaseUrl/windows/ice.exe" -OutFile $asset; Invoke-WebRequest "$BaseUrl/SHA256SUMS.txt" -OutFile $sums; $line=Get-Content $sums | Where-Object { $_ -match '  windows/ice.exe$' } | Select-Object -First 1; if (-not $line -or $line -notmatch '^([a-fA-F0-9]{64})') { throw 'No checksum for windows/ice.exe.' }; if ((Get-FileHash $asset -Algorithm SHA256).Hash -ine $Matches[1]) { throw 'Checksum mismatch.' }; New-Item -ItemType Directory -Force -Path $root | Out-Null; Copy-Item $asset (Join-Path $root 'ice.exe') -Force; & (Join-Path $root 'ice.exe') --version; if ($LASTEXITCODE -ne 0) { throw 'Installed binary failed its version check.' }; Write-Host "ICE installed to $root" -ForegroundColor Cyan } finally { Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue }
